1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"container/list"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"sync"
14		"syscall"
15	)
16	
17	// maxProcessTime is the largest legal processing time: non-negative int64
18	// Unix milliseconds, up to the int64 ceiling.
19	const maxProcessTime = math.MaxInt64
20	
21	// Durable queue statuses. Pending and waiting are live; the rest are terminal.
22	const (
23		StatusPending    = "pending"        // accepted, not processed for the first time yet
24		StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
25		StatusSuccess    = "success"        // recorded locally and nonce consumed
26		StatusReplay     = "replay"         // nonce combination already consumed by another message
27		StatusExpired    = "expired"        // absolute expiry reached before delivery
28		StatusUnknownSrc = "unknown-source" // source chain was never registered
29	)
30	
31	// Common errors. Callers can compare with errors.Is.
32	var (
33		// ErrConflict is returned when an id is reused with different message content.
34		ErrConflict = errors.New("message id conflict: existing record has different content")
35		// ErrHeaderConflict is returned when a trusted header is submitted at the
36		// height of the accepted highest trusted header with a different root. The
37		// accepted trusted header is kept and the queue remains usable.
38		ErrHeaderConflict = errors.New("trusted header conflict: different root at the accepted height")
39		// ErrTerminal is returned when re-submitting a terminal id or attempting to
40		// reactivate it.
41		ErrTerminal = errors.New("message is terminal and cannot be reactivated")
42		// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
43		ErrInvalidArg = errors.New("invalid argument")
44		// ErrLocked is returned when another process holds the state directory open.
45		ErrLocked = errors.New("state directory is locked by another process")
46		// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
47		ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
48		// ErrStorage is returned after a storage failure; the queue must be reopened.
49		ErrStorage = errors.New("storage failure; queue must be reopened")
50	)
51	
52	// Envelope is a submitted message together with its absolute expiry time.
53	type Envelope struct {
54		Message Message
55		// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
56		ExpiresAt int64
57	}
58	
59	// Record is the full persisted state of one submitted message.
60	type Record struct {
61		Msg        Envelope
62		Status     string
63		Reason     string
64		Seq        int64 // submission order, zero-based
65		Attempts   int   // number of processing attempts
66		NextRetry  int64 // 0 when not yet processed, or terminal
67		LastProcAt int64 // processing time of the most recent attempt
68	}
69	
70	// Query is the user-visible view of a Record.
71	type Query struct {
72		ID        string
73		From      string
74		To        string
75		Nonce     uint64
76		Payload   string
77		ProofAt   int64
78		ExpiresAt int64
79		Status    string
80		Reason    string
81		NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
82		Attempts  int
83	}
84	
85	// AdvanceReport is the outcome of one Advance call.
86	type AdvanceReport struct {
87		Now     int64
88		Results []Result
89	}
90	
91	// Result describes what happened to one message during an Advance.
92	type Result struct {
93		ID     string `json:"id"`
94		Status string `json:"status"`
95		Reason string `json:"reason"`
96	}
97	
98	// headerState records the headers seen for one chain: the latest header
99	// written (any trust level) and the highest trusted header accepted. Proof
100	// coverage is determined solely by the highest trusted header — a later
101	// untrusted header, even at a greater height, can never lower or invalidate
102	// it. The zero value is a chain with no recorded headers.
103	type headerState struct {
104		latest  Header
105		trusted *Header
106	}
107	
108	// Queue is a durable local outbox backed by a state directory. A single
109	// Queue owns the directory for writes; other processes attempting to Open the
110	// same directory fail with ErrLocked. It is safe for concurrent use by
111	// multiple goroutines, and a success record plus its nonce consumption commit
112	// as one durable unit.
113	type Queue struct {
114		mu sync.Mutex
115	
116		store  *store
117		flock  *os.File
118		broken bool // a storage write failed; all further mutations fail
119	
120		now      int64                   // last advanced Unix-ms time, 0 = never advanced
121		sources  map[string]bool         // registered source chains
122		headers  map[string]*headerState // per-chain recorded headers (latest + highest trusted)
123		records  map[string]*Record      // by message id
124		order    *pendingOrder           // non-terminal messages, first-submission order
125		consumed map[consumeToken]string // (source, destination, nonce) -> successful message id
126		nextSeq  int64
127	}
128	
129	// pendingOrder is the set of non-terminal (live) messages kept in strict
130	// first-submission order. It is an intrusive doubly-linked list indexed by
131	// message id: a message leaving the order when it terminalizes unlinks itself
132	// in constant time, instead of a linear slice scan followed by shifting every
133	// later entry. The total order-maintenance work of one advance therefore grows
134	// only with the number of non-terminal messages present when the advance
135	// began — traversed a constant number of times — never with the number of
136	// terminal results already accumulated in history. Traversal is stable under
137	// unlinking the current node, so terminalizing during a sweep neither visits a
138	// dead node nor reorders the survivors.
139	type pendingOrder struct {
140		l     *list.List               // each element's Value is the live message id
141		index map[string]*list.Element // live id -> its node
142	}
143	
144	func newPendingOrder(hint int) *pendingOrder {
145		return &pendingOrder{
146			l:     list.New(),
147			index: make(map[string]*list.Element, hint),
148		}
149	}
150	
151	// pushBack appends a newly submitted live message after every earlier one.
152	func (p *pendingOrder) pushBack(id string) {
153		if _, ok := p.index[id]; ok {
154			return
155		}
156		p.index[id] = p.l.PushBack(id)
157	}
158	
159	// remove unlinks a terminalized message in constant time. Removing an id that
160	// is no longer live is a no-op.
161	func (p *pendingOrder) remove(id string) {
162		if el, ok := p.index[id]; ok {
163			p.l.Remove(el)
164			delete(p.index, id)
165		}
166	}
167	
168	func (p *pendingOrder) len() int { return p.l.Len() }
169	
170	// ids returns the live ids in first-submission order. It is used by the
171	// in-package tests; hot paths traverse the nodes directly instead.
172	func (p *pendingOrder) ids() []string {
173		out := make([]string, 0, p.l.Len())
174		for el := p.l.Front(); el != nil; el = el.Next() {
175			out = append(out, el.Value.(string))
176		}
177		return out
178	}
179	
180	// Open opens (creating if needed) a persistent queue backed by stateDir. It
181	// takes an exclusive process lock on the directory and refuses to start when
182	// the on-disk state is corrupt or in an unsupported format, never clearing it.
183	func Open(stateDir string) (*Queue, error) {
184		if stateDir == "" {
185			return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
186		}
187		if err := os.MkdirAll(stateDir, 0o755); err != nil {
188			return nil, fmt.Errorf("create state directory: %w", err)
189		}
190		abs, err := filepath.Abs(stateDir)
191		if err != nil {
192			return nil, fmt.Errorf("resolve state directory: %w", err)
193		}
194	
195		lockPath := filepath.Join(abs, "lock")
196		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
197		if err != nil {
198			return nil, fmt.Errorf("open lock file: %w", err)
199		}
200		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
201			lock.Close()
202			return nil, fmt.Errorf("%w: %v", ErrLocked, err)
203		}
204	
205		st, state, err := openStore(abs)
206		if err != nil {
207			syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
208			lock.Close()
209			return nil, err
210		}
211	
212		q := &Queue{
213			store:    st,
214			flock:    lock,
215			sources:  state.sources,
216			headers:  state.headers,
217			records:  state.records,
218			consumed: state.consumed,
219			now:      state.now,
220			nextSeq:  state.nextSeq,
221			order:    newPendingOrder(len(state.records)),
222		}
223		q.reconstructOrder()
224		st.snap = q.snapshot
225		return q, nil
226	}
227	
228	// reconstructOrder fills the empty live order with the non-terminal records in
229	// submission (seq) order. It runs once, when opening a state directory: the
230	// per-advance cost of maintaining the order never depends on how many terminal
231	// records history has accumulated.
232	func (q *Queue) reconstructOrder() {
233		seqs := make([]int64, 0, len(q.records))
234		live := map[int64]string{}
235		for id, rec := range q.records {
236			if isTerminal(rec.Status) {
237				continue
238			}
239			seqs = append(seqs, rec.Seq)
240			live[rec.Seq] = id
241		}
242		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
243		for _, seq := range seqs {
244			q.order.pushBack(live[seq])
245		}
246	}
247	
248	// snapshot returns a detached copy of live state for log compaction. Callers
249	// must hold mu.
250	func (q *Queue) snapshot() *loadedState {
251		s := &loadedState{
252			sources:  map[string]bool{},
253			headers:  map[string]*headerState{},
254			records:  map[string]*Record{},
255			consumed: map[consumeToken]string{},
256			now:      q.now,
257			nextSeq:  q.nextSeq,
258		}
259		for c := range q.sources {
260			s.sources[c] = true
261		}
262		for c, h := range q.headers {
263			cp := &headerState{latest: h.latest}
264			if h.trusted != nil {
265				t := *h.trusted
266				cp.trusted = &t
267			}
268			s.headers[c] = cp
269		}
270		for id, rec := range q.records {
271			cp := *rec
272			s.records[id] = &cp
273		}
274		for k, v := range q.consumed {
275			s.consumed[k] = v
276		}
277		return s
278	}
279	
280	// Close flushes, releases the directory lock and closes the queue.
281	func (q *Queue) Close() error {
282		q.mu.Lock()
283		defer q.mu.Unlock()
284		if q.flock == nil {
285			return nil
286		}
287		var err error
288		if !q.broken {
289			err = q.store.close()
290		} else {
291			q.store.forceClose()
292		}
293		syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
294		q.flock.Close()
295		q.flock = nil
296		return err
297	}
298	
299	// fail locks in a storage failure: the log tail may be partially written, so
300	// no further appends are allowed in this process (another append would turn a
301	// truncatable torn tail into unrecoverable corruption).
302	func (q *Queue) fail(op string, err error) error {
303		q.broken = true
304		return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
305	}
306	
307	func (q *Queue) checkWritable() error {
308		if q.flock == nil {
309			return fmt.Errorf("%w: queue is closed", ErrStorage)
310		}
311		if q.broken {
312			return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
313		}
314		return nil
315	}
316	
317	// RegisterSource records that messages may originate from chain. Idempotent.
318	func (q *Queue) RegisterSource(chain string) error {
319		if chain == "" {
320			return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
321		}
322		q.mu.Lock()
323		defer q.mu.Unlock()
324		if err := q.checkWritable(); err != nil {
325			return err
326		}
327		if q.sources[chain] {
328			return nil
329		}
330		if err := q.store.appendRegisterSource(chain); err != nil {
331			return q.fail("register source", err)
332		}
333		q.sources[chain] = true
334		return q.maybeCompact()
335	}
336	
337	// UpsertHeader records a header for a chain. The latest header is always
338	// recorded, but proof coverage is determined solely by the highest trusted
339	// header accepted for the chain:
340	//
341	//   - the first trusted header establishes coverage;
342	//   - a higher trusted header advances it;
343	//   - a lower trusted header, or an untrusted header of any height, is
344	//     recorded but can never lower or invalidate established coverage;
345	//   - a trusted header at the current highest trusted height with the same
346	//     root is an idempotent no-op;
347	//   - a trusted header at that height with a different root is an
348	//     ErrHeaderConflict: the accepted trusted header is kept and the queue
349	//     remains usable.
350	//
351	// Header updates never bypass retry scheduling, never process messages, and
352	// never reactivate terminal messages.
353	func (q *Queue) UpsertHeader(h Header) error {
354		if h.Chain == "" {
355			return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
356		}
357		if h.Height < 0 {
358			return fmt.Errorf("%w: negative header height", ErrInvalidArg)
359		}
360		q.mu.Lock()
361		defer q.mu.Unlock()
362		if err := q.checkWritable(); err != nil {
363			return err
364		}
365		hs := q.headers[h.Chain]
366		if hs == nil {
367			hs = &headerState{}
368			q.headers[h.Chain] = hs
369		}
370		if h.Trusted && hs.trusted != nil &&
371			h.Height == hs.trusted.Height && h.Root != hs.trusted.Root {
372			return fmt.Errorf("%w: chain %q height %d: submitted root %q conflicts with accepted root %q",
373				ErrHeaderConflict, h.Chain, h.Height, h.Root, hs.trusted.Root)
374		}
375		if err := q.store.appendHeader(h); err != nil {
376			return q.fail("upsert header", err)
377		}
378		hs.latest = h
379		if h.Trusted && (hs.trusted == nil || h.Height > hs.trusted.Height) {
380			t := h
381			hs.trusted = &t
382		}
383		return q.maybeCompact()
384	}
385	
386	// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
387	// means never expire). Re-submitting the same id with identical content
388	// returns the existing record without adding a queue entry; the same id with
389	// different content returns ErrConflict and leaves the original untouched;
390	// re-submitting a terminal id returns ErrTerminal. Success is reported only
391	// after the submission is durably persisted.
392	func (q *Queue) Submit(env Envelope) (*Record, error) {
393		m := env.Message
394		if m.ID == "" {
395			return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
396		}
397		if m.From == "" || m.To == "" {
398			return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
399		}
400		if m.ProofAt < 0 {
401			return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
402		}
403		if env.ExpiresAt < 0 {
404			return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
405		}
406	
407		q.mu.Lock()
408		defer q.mu.Unlock()
409		if err := q.checkWritable(); err != nil {
410			return nil, err
411		}
412	
413		if existing, ok := q.records[m.ID]; ok {
414			if isTerminal(existing.Status) {
415				return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
416			}
417			if sameEnvelope(existing.Msg, env) {
418				out := *existing
419				return &out, nil
420			}
421			return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
422		}
423	
424		rec := &Record{
425			Msg:    env,
426			Status: StatusPending,
427			Reason: "awaiting first processing",
428			Seq:    q.nextSeq,
429		}
430		if err := q.store.appendSubmit(rec); err != nil {
431			return nil, q.fail("submit", err)
432		}
433		q.records[m.ID] = rec
434		q.order.pushBack(m.ID)
435		q.nextSeq++
436		if err := q.maybeCompact(); err != nil {
437			return nil, err
438		}
439		out := *rec
440		return &out, nil
441	}
442	
443	// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
444	// be advanced repeatedly; going backwards is rejected and changes nothing.
445	//
446	// Each advance, in submission order:
447	//  1. due messages (new messages are due on the next advance; others when now
448	//     has reached their next retry time) are evaluated for replay and expiry,
449	//     replay winning on a tie and now == ExpiresAt counting as expired, then
450	//     for source registration and trusted-header coverage, and finally
451	//     delivered;
452	//  2. afterwards every remaining non-terminal message, regardless of its
453	//     retry schedule, is re-checked for replay and expiry at the new time.
454	//
455	// Unregistered sources are permanently rejected as unknown-source; registered
456	// sources without a trusted header covering the proof height stay waiting and
457	// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
458	// doubling to a 60-second cap, measured from the actual processing time;
459	// jumping over several intervals still costs one attempt.
460	//
461	// The retry instant saturates at the int64 ceiling: a waiting message whose
462	// computed retry would overflow is scheduled for math.MaxInt64 instead, never
463	// a negative, zero or earlier-than-processing instant. Once such a message has
464	// been processed at the ceiling, every later advance is at the same instant,
465	// so it is never due again and keeps its waiting status, reason, attempt
466	// count and ceiling retry time; it is neither reprocessed nor reported again
467	// as a waiting result. Replay and expiry checks, which run independently of
468	// the retry schedule, still apply to it, and a header update alone never
469	// delivers it.
470	func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
471		if nowMs < 0 {
472			return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
473		}
474		q.mu.Lock()
475		defer q.mu.Unlock()
476		if err := q.checkWritable(); err != nil {
477			return nil, err
478		}
479		if q.now != 0 && nowMs < q.now {
480			return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
481		}
482	
483		report := &AdvanceReport{Now: nowMs}
484	
485		// Phase 1: due messages, first-submission order. Traversal walks the live
486		// list directly and captures the successor before processing, because a
487		// result that terminalizes — and therefore unlinks — the current node
488		// leaves that node without a successor afterwards. Doing so neither
489		// corrupts the walk nor changes any survivor's position. Each unlink is
490		// constant-time, so maintaining the order across the whole phase costs
491		// only one pass over the live messages.
492		el := q.order.l.Front()
493		for el != nil {
494			id := el.Value.(string)
495			el = el.Next()
496			rec := q.records[id]
497			if rec == nil || isTerminal(rec.Status) {
498				continue
499			}
500			due := rec.Attempts == 0 || retryDue(rec, nowMs)
501			if !due {
502				continue
503			}
504			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
505				return nil, err
506			} else if done {
507				report.Results = append(report.Results, r)
508				continue
509			}
510			r, err := q.processDue(rec, nowMs)
511			if err != nil {
512				return nil, err
513			}
514			report.Results = append(report.Results, r)
515		}
516	
517		// Phase 2: replay/expiry hold for every non-terminal message at the new
518		// time, even while its retry backoff is still running. Messages that
519		// terminalized in phase 1 are already gone from the list, so this sweep
520		// (plus every constant-time unlink it triggers) again costs one linear
521		// pass over the remaining live messages only — never over history.
522		el = q.order.l.Front()
523		for el != nil {
524			id := el.Value.(string)
525			// Capture the successor before processing: checkReplayExpiry may
526			// terminalize — and unlink — this very node.
527			el = el.Next()
528			rec := q.records[id]
529			if rec == nil || isTerminal(rec.Status) {
530				continue
531			}
532			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
533				return nil, err
534			} else if done {
535				report.Results = append(report.Results, r)
536			}
537		}
538	
539		if err := q.store.appendAdvance(nowMs); err != nil {
540			return nil, q.fail("advance", err)
541		}
542		q.now = nowMs
543		if err := q.maybeCompact(); err != nil {
544			return nil, err
545		}
546		return report, nil
547	}
548	
549	// maybeCompact rewrites the WAL as a snapshot once it grows past the
550	// threshold. Live state already reflects every acknowledged append, so the
551	// snapshot cannot lose records. A compaction failure is a storage failure:
552	// the queue is marked broken and must be reopened.
553	func (q *Queue) maybeCompact() error {
554		if !q.store.needsCompaction() {
555			return nil
556		}
557		if err := q.store.compact(q.snapshot()); err != nil {
558			return q.fail("compact log", err)
559		}
560		return nil
561	}
562	
563	// checkReplayExpiry terminalizes rec when its nonce was consumed by another
564	// message or its absolute expiry has been reached. Replay wins when both
565	// hold. The bool reports whether the message was terminalized.
566	func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
567		id := rec.Msg.Message.ID
568		token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
569		if winner, taken := q.consumed[token]; taken && winner != id {
570			reason := "nonce combination already consumed by message " + winner
571			r, err := q.applyOutcome(rec, now, terminalOutcome(StatusReplay, reason))
572			if err != nil {
573				return Result{}, false, err
574			}
575			return r, true, nil
576		}
577		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
578			reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
579			r, err := q.applyOutcome(rec, now, terminalOutcome(StatusExpired, reason))
580			if err != nil {
581				return Result{}, false, err
582			}
583			return r, true, nil
584		}
585		return Result{}, false, nil
586	}
587	
588	// processDue classifies a due message against source registration and header
589	// trust, or delivers it.
590	func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
591		m := rec.Msg.Message
592		if !q.sources[m.From] {
593			reason := "unknown source chain " + m.From
594			return q.applyOutcome(rec, now, terminalOutcome(StatusUnknownSrc, reason))
595		}
596		hs := q.headers[m.From]
597		if hs == nil || hs.trusted == nil || hs.trusted.Height < m.ProofAt {
598			cur := int64(0)
599			if hs != nil && hs.trusted != nil {
600				cur = hs.trusted.Height
601			}
602			reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", m.ProofAt, cur)
603			return q.applyOutcome(rec, now, waitingOutcome(reason))
604		}
605	
606		// Deliver: success record and nonce consumption are one log entry. The
607		// coverage height is the highest trusted header actually accepted — never
608		// a higher untrusted header.
609		token := newConsumeToken(m.From, m.To, m.Nonce)
610		reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(hs.trusted.Height, 10)
611		return q.applyOutcome(rec, now, successOutcome(reason, token))
612	}
613	
614	// outcome describes one processing result independently of which path found
615	// it: waiting for header coverage, delivery, or one of the terminal rejections
616	// (replay, expiry, unknown source). It carries only the business differences
617	// between the result kinds; the rules shared by every result — one more
618	// attempt, the processing-time stamp, how the result is persisted and when the
619	// record may change — live solely in applyOutcome.
620	type outcome struct {
621		status string
622		reason string
623		// consume is set only for success: the message's own
624		// (source, destination, nonce) triple, attributed to that message. No
625		// other result kind consumes a nonce.
626		consume *consumeToken
627		// op labels the failing operation in the storage error for this kind of
628		// result, keeping each path's historical error wording.
629		op string
630	}
631	
632	// waitingOutcome keeps the message live with its status unchanged in kind and
633	// its existing backoff machinery: the actual retry instant is computed by
634	// applyOutcome from the processing time and the new attempt number.
635	func waitingOutcome(reason string) outcome {
636		return outcome{status: StatusWaiting, reason: reason, op: "schedule retry"}
637	}
638	
639	// terminalOutcome settles a non-success result that ends processing: replay,
640	// expiry or unknown-source. Such results clear the retry schedule, consume no
641	// nonce and leave the live processing order.
642	func terminalOutcome(status, reason string) outcome {
643		return outcome{status: status, reason: reason, op: "terminalize"}
644	}
645	
646	// successOutcome delivers the message: it clears the retry schedule, leaves
647	// the processing order and records consumption of the message's own triple,
648	// attributed to the message itself, in the same durable record as the success
649	// state.
650	func successOutcome(reason string, token consumeToken) outcome {
651		return outcome{status: StatusSuccess, reason: reason, consume: &token, op: "deliver"}
652	}
653	
654	// applyOutcome is the single path through which every processing result is
655	// saved and takes effect. It persists the result first and touches the record
656	// only after the save is acknowledged, so a failed write changes nothing: the
657	// message keeps its previous status, reason, attempt count, processing time
658	// and retry schedule, its nonce is not consumed, and earlier results already
659	// acknowledged in the same advance stay in force. On success every result
660	// counts exactly one more attempt and stamps LastProcAt with the processing
661	// time; a waiting result additionally keeps its saturated backoff schedule,
662	// while success and terminal results clear the retry time and leave the
663	// processing order; success also records the nonce consumption.
664	func (q *Queue) applyOutcome(rec *Record, now int64, oc outcome) (Result, error) {
665		id := rec.Msg.Message.ID
666		attempt := rec.Attempts + 1
667		nextRetry := int64(0)
668		if oc.status == StatusWaiting {
669			nextRetry = nextRetryAt(now, attempt)
670		}
671		if err := q.store.appendOutcome(now, rec, attempt, nextRetry, oc); err != nil {
672			return Result{}, q.fail(oc.op, err)
673		}
674		rec.Attempts = attempt
675		rec.LastProcAt = now
676		rec.Status = oc.status
677		rec.Reason = oc.reason
678		rec.NextRetry = nextRetry
679		if oc.consume != nil {
680			q.consumed[*oc.consume] = id
681		}
682		if isTerminal(oc.status) {
683			q.order.remove(id)
684		}
685		return Result{ID: id, Status: oc.status, Reason: oc.reason}, nil
686	}
687	
688	// retryDue reports whether a waiting record's next retry is reached at now.
689	// Backoff delays are always positive, so every representable retry lies
690	// strictly after the processing time that scheduled it; a waiting message is
691	// therefore evaluated at most once per distinct processing time. The only
692	// instant where the retry cannot lie later is the int64 ceiling: there the
693	// schedule saturates to the ceiling itself. Once the message was processed at
694	// the ceiling, every legal advance is at the same instant, so the retry can
695	// never be reached "later" — treating equal time as due would reprocess the
696	// message on every advance, inflate attempts and re-report waiting forever.
697	func retryDue(rec *Record, now int64) bool {
698		if now < rec.NextRetry {
699			return false
700		}
701		return now != rec.LastProcAt
702	}
703	
704	// nextRetryAt returns the retry instant after the attempt-th processing at
705	// now: now plus the backoff delay, saturated at math.MaxInt64. Saturation
706	// keeps the scheduled retry non-negative, never zero (when processed at a
707	// positive time) and never earlier than the processing time; when the true
708	// retry overflows int64 the ceiling is the nearest representable instant.
709	func nextRetryAt(now int64, attempt int) int64 {
710		delay := nextRetryDelay(attempt)
711		if now > maxProcessTime-delay {
712			return maxProcessTime // now+delay would overflow; delay is at most 60000
713		}
714		return now + delay
715	}
716	
717	// nextRetryDelay is the backoff after the attempt-th processing (1-based):
718	// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
719	func nextRetryDelay(attempt int) int64 {
720		if attempt < 1 {
721			attempt = 1
722		}
723		if attempt > 6 {
724			return 60_000
725		}
726		return int64(1) << (attempt - 1) * 1000
727	}
728	
729	func isTerminal(status string) bool {
730		switch status {
731		case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
732			return true
733		}
734		return false
735	}
736	
737	func sameEnvelope(a, b Envelope) bool {
738		return a.ExpiresAt == b.ExpiresAt &&
739			a.Message.ID == b.Message.ID &&
740			a.Message.From == b.Message.From &&
741			a.Message.To == b.Message.To &&
742			a.Message.Nonce == b.Message.Nonce &&
743			a.Message.Payload == b.Message.Payload &&
744			a.Message.ProofAt == b.Message.ProofAt
745	}
746	
747	// Query returns the current state of a message.
748	func (q *Queue) Query(id string) (Query, bool) {
749		q.mu.Lock()
750		defer q.mu.Unlock()
751		rec, ok := q.records[id]
752		if !ok {
753			return Query{}, false
754		}
755		return toQuery(rec), true
756	}
757	
758	// Queries returns all records in first-submission order.
759	func (q *Queue) Queries() []Query {
760		q.mu.Lock()
761		defer q.mu.Unlock()
762		out := make([]Query, 0, len(q.records))
763		for _, rec := range q.records {
764			out = append(out, toQuery(rec))
765		}
766		sort.Slice(out, func(i, j int) bool {
767			return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
768		})
769		return out
770	}
771	
772	// Now returns the last advanced processing time, or 0 if never advanced.
773	func (q *Queue) Now() int64 {
774		q.mu.Lock()
775		defer q.mu.Unlock()
776		return q.now
777	}
778	
779	func toQuery(rec *Record) Query {
780		return Query{
781			ID:        rec.Msg.Message.ID,
782			From:      rec.Msg.Message.From,
783			To:        rec.Msg.Message.To,
784			Nonce:     rec.Msg.Message.Nonce,
785			Payload:   rec.Msg.Message.Payload,
786			ProofAt:   rec.Msg.Message.ProofAt,
787			ExpiresAt: rec.Msg.ExpiresAt,
788			Status:    rec.Status,
789			Reason:    rec.Reason,
790			NextRetry: rec.NextRetry,
791			Attempts:  rec.Attempts,
792		}
793	}
794

