220		}
221		if _, ok := q.Query(missingID); ok {
222			t.Fatalf("unacknowledged torn record %q must not exist", missingID)
223		}
224		if q.nextSeq != 1 {
225			t.Fatalf("nextSeq must resume after the last intact submit, got %d", q.nextSeq)
226		}
