228		// that the dropped tail record never acquired.
229		rec, err := q.Submit(env("m3", "a", "b", 3, 10, 0))
230		if err != nil {
231			t.Fatalf("recovered queue must accept new submits: %v", err)
232		}
233		if rec.Seq != 1 {
234			t.Fatalf("new submit should reuse seq 1, got %d", rec.Seq)
235		}
236		if _, err := q.Advance(2000); err != nil {
237			t.Fatal(err)
238		}
239		if r := statusOf(t, q, "m3"); r.Status != StatusSuccess {
240			t.Fatalf("new message should deliver on recovered queue: %+v", r)
241		}
