245	// still reject the directory and preserve every byte.
246	func TestMidLogCorruptionStillRejectedAndUntouched(t *testing.T) {
247		dir := t.TempDir()
248		q, err := Open(dir)
249		if err != nil {
250			t.Fatal(err)
251		}
252		q.RegisterSource("a")
253		q.Submit(env("m1", "a", "b", 1, 10, 0))
