259		raw, err := os.ReadFile(filepath.Join(dir, logName))
260		if err != nil {
261			t.Fatal(err)
262		}
263		// The first frame is the version record; flip a byte in the second frame
264		// (the source entry) so its checksum fails before EOF.
265		bad := append([]byte(nil), raw...)
266		pos := len(logMagic)
267		// Skip the whole version frame to land on the record after it.
268		vn := int(binary.BigEndian.Uint32(bad[pos:]))
269		pos += frameHeaderSize + vn + frameCRCsSize
270		bad[pos+frameHeaderSize+1] ^= 0xFF
271	
272		d := t.TempDir()
273		writeRawLog(t, d, bad)
274		assertCorruptAndUntouched(t, d, bad)
275	}
