1	package relayproof
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// Header roots are arbitrary byte strings compared byte for byte. A root
13	// holding invalid UTF-8 bytes must survive saving, reopening and log
14	// compaction exactly: JSON string encoding would otherwise silently rewrite
15	// such bytes to U+FFFD, making the resubmitted original root conflict with
16	// its own saved value while the replacement character is wrongly accepted.
17	
18	const replacementCharRoot = "�"
19	
20	// requireHeaderAccepted requires a trusted same-height save of root to be
21	// accepted against the currently accepted trusted root.
22	func requireHeaderAccepted(t *testing.T, q *Queue, chain string, height int64, root string) {
23		t.Helper()
24		if err := q.UpsertHeader(Header{Chain: chain, Height: height, Root: root, Trusted: true}); err != nil {
25			t.Fatalf("same root at trusted height %d must be accepted: %v", height, err)
26		}
27	}
28	
29	// requireHeaderConflict requires a trusted same-height save of root to fail
30	// with ErrHeaderConflict, and the accepted trusted root to stay wantAccepted.
31	func requireHeaderConflict(t *testing.T, q *Queue, chain string, height int64, root, wantAccepted string) {
32		t.Helper()
33		err := q.UpsertHeader(Header{Chain: chain, Height: height, Root: root, Trusted: true})
34		if !errors.Is(err, ErrHeaderConflict) {
35			t.Fatalf("different root at trusted height %d: want ErrHeaderConflict, got %v", height, err)
36		}
37		hs := q.headers[chain]
38		if hs == nil || hs.trusted == nil || hs.trusted.Root != wantAccepted || hs.trusted.Height != height {
39			t.Fatalf("accepted trusted header changed after conflict: %+v", hs.trusted)
40		}
41	}
42	
43	func reopen(t *testing.T, dir string) *Queue {
44		t.Helper()
45		q, err := Open(dir)
46		if err != nil {
47			t.Fatalf("reopen: %v", err)
48		}
49		return q
50	}
51	
52	// An invalid-UTF-8 root is preserved byte-for-byte through save, close,
53	// reopen and compaction: the identical byte sequence stays an idempotent
54	// accept at the trusted height, while a root differing in any byte — and the
55	// legal character U+FFFD, which must never be merged with invalid bytes —
56	// conflicts, before and after every persistence boundary.
57	func TestHeaderRootInvalidUTF8PreservedAcrossReopenAndCompaction(t *testing.T) {
58		rootFF := string([]byte{0xFF})
59		rootFE := string([]byte{0xFE})
60		mixed := "pre" + string([]byte{0xFF}) + "post"
61	
62		dir := t.TempDir()
63		q, err := Open(dir)
64		if err != nil {
65			t.Fatal(err)
66		}
67		if err := q.RegisterSource("a"); err != nil {
68			t.Fatal(err)
69		}
70		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: rootFF, Trusted: true}); err != nil {
71			t.Fatalf("save invalid-UTF-8 root: %v", err)
72		}
73		if err := q.UpsertHeader(Header{Chain: "b", Height: 7, Root: mixed, Trusted: true}); err != nil {
74			t.Fatalf("save partially invalid root: %v", err)
75		}
76	
77		check := func(t *testing.T, q *Queue) {
78			t.Helper()
79			// The exact same bytes are accepted idempotently.
80			requireHeaderAccepted(t, q, "a", 100, rootFF)
81			requireHeaderAccepted(t, q, "b", 7, mixed)
82			// Any single-byte difference is a conflict, and U+FFFD is a distinct
83			// root, never the canonical form of invalid bytes.
84			requireHeaderConflict(t, q, "a", 100, rootFE, rootFF)
85			requireHeaderConflict(t, q, "a", 100, replacementCharRoot, rootFF)
86			requireHeaderConflict(t, q, "b", 7, replacementCharRoot, mixed)
87		}
88		t.Run("same instance", func(t *testing.T) { check(t, q) })
89		if err := q.Close(); err != nil {
90			t.Fatal(err)
91		}
92	
93		q = reopen(t, dir)
94		t.Run("after reopen", func(t *testing.T) { check(t, q) })
95	
96		// A higher untrusted header and a lower trusted header with different
97		// roots are recorded but never displace the accepted trusted root.
98		if err := q.UpsertHeader(Header{Chain: "a", Height: 200, Root: rootFE, Trusted: false}); err != nil {
99			t.Fatal(err)
100		}
101		if err := q.UpsertHeader(Header{Chain: "a", Height: 50, Root: rootFE, Trusted: true}); err != nil {
102			t.Fatal(err)
103		}
104		check(t, q)
105	
106		// Force a compaction cycle; the snapshot must carry the exact bytes too.
107		if err := q.store.compact(q.snapshot()); err != nil {
108			t.Fatalf("compact: %v", err)
109		}
110		if err := q.Close(); err != nil {
111			t.Fatal(err)
112		}
113	
114		q = reopen(t, dir)
115		t.Run("after compaction and reopen", func(t *testing.T) { check(t, q) })
116		if err := q.Close(); err != nil {
117			t.Fatal(err)
118		}
119	
120		// The persisted log holds the raw bytes base64-encoded and never the
121		// replacement character.
122		raw, err := os.ReadFile(filepath.Join(dir, logName))
123		if err != nil {
124			t.Fatal(err)
125		}
126		if !bytes.Contains(raw, []byte(`"rootB64":"`)) {
127			t.Fatalf("invalid-UTF-8 root not stored byte-exactly: %s", raw)
128		}
129		if bytes.Contains(raw, []byte(replacementCharRoot)) {
130			t.Fatalf("log contains U+FFFD: a root was silently rewritten: %s", raw)
131		}
132	}
133	
134	// Valid-UTF-8 roots — plain text, empty, whitespace, U+FFFD itself — keep the
135	// historical plain "root" field, so logs written by older builds and this
136	// build remain byte-identical and existing state directories keep working.
137	func TestHeaderRootValidUTF8KeepsHistoricalEncoding(t *testing.T) {
138		dir := t.TempDir()
139		q, err := Open(dir)
140		if err != nil {
141			t.Fatal(err)
142		}
143		roots := []string{"0xaaa", "", " spaced ", replacementCharRoot}
144		for i, root := range roots {
145			chain := string(rune('c' + i))
146			if err := q.UpsertHeader(Header{Chain: chain, Height: 5, Root: root, Trusted: true}); err != nil {
147				t.Fatalf("save root %q: %v", root, err)
148			}
149		}
150		if err := q.Close(); err != nil {
151			t.Fatal(err)
152		}
153	
154		raw, err := os.ReadFile(filepath.Join(dir, logName))
155		if err != nil {
156			t.Fatal(err)
157		}
158		if bytes.Contains(raw, []byte("rootB64")) {
159			t.Fatalf("valid-UTF-8 roots must keep the plain root field: %s", raw)
160		}
161		if !bytes.Contains(raw, []byte(`"root":"0xaaa"`)) {
162			t.Fatalf("plain root missing from log: %s", raw)
163		}
164	
165		// Reopen: every root means exactly what it meant before, including the
166		// empty root and U+FFFD as an ordinary legal character.
167		q = reopen(t, dir)
168		defer q.Close()
