		t.Fatalf("want ErrHeaderConflict, got %v", err)
	}
	if !strings.Contains(err.Error(), `\xfe`) || !strings.Contains(err.Error(), `\xff`) {
		t.Fatalf("conflict error must name both roots distinctly: %v", err)
